Algorithm Votacion
  Define votos As Dictionary<String, Integer> <- dictionary();
  Define nombre As String;
  Read nombre;
  While nombre <> "fin" Do
    Switch votos.find(nombre) Do
      Some(cantidad): votos[nombre] <- cantidad + 1;
      None: votos[nombre] <- 1;
    EndSwitch
    Read nombre;
  EndWhile
  Define ganador As String <- "";
  Define mayor As Integer <- 0;
  For Each candidato In votos.keys() Do
    If votos[candidato] > mayor Or (votos[candidato] = mayor And candidato < ganador) Then
      ganador <- candidato;
      mayor <- votos[candidato];
    EndIf
  EndFor
  If mayor = 0 Then
    Write "Sin votos";
  Else
    Write ganador, " ", mayor;
  EndIf
EndAlgorithm
